import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Geometry: plane sized to atlas region aspect ratio (512x320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load texture (cached synchronously)
  const map = ctx.textureLoader.load(config.imageUrl);

  // Configure atlas region (0, 0, 512, 320) in 1024x1024 atlas
  map.offset.set(0, 0);
  map.repeat.set(0.5, 0.3125);

  // Create TSL material
  const mapNode = texture(map);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: mapNode,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene position
  const pos = config.scenePosition || {};
  group.position.set(pos.x || 0, pos.y || 0, pos.z || 0);

  // Apply rotation
  if (pos.rotationXYZ) {
    group.rotation.order = 'YXZ';
    group.rotation.set(pos.rotationXYZ[0] || 0, pos.rotationXYZ[1] || 0, pos.rotationXYZ[2] || 0);
  }

  // Apply scale
  if (pos.scaleXYZ) {
    group.scale.set(pos.scaleXYZ[0] || 1, pos.scaleXYZ[1] || 1, pos.scaleXYZ[2] || 1);
  }

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    map.dispose();
  };

  // Event handlers (empty for static element)
  group.userData.handlers = {};

  return group;
}
